-- Contenido editable de la landing (HU-32). No incluye imágenes.
-- Puede repetirse: conserva cualquier contenido editado anteriormente.
CREATE TABLE IF NOT EXISTS contenido_landing (
  id TINYINT UNSIGNED NOT NULL,
  contenido JSON NOT NULL,
  actualizado_en TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  CONSTRAINT chk_landing_unica CHECK (id = 1)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;

INSERT INTO contenido_landing (id, contenido)
SELECT 1, '{"nombre_parroquia":"Parroquia San Pedro Nolasco","lema":"Casa de oración · Guatemala","titulo_principal":"Una comunidad que camina unida en la fe","descripcion_principal":"Somos una parroquia viva al servicio de las familias de nuestro barrio. Celebramos, acompañamos y servimos — con las puertas siempre abiertas para quien busca consuelo, formación o un lugar donde pertenecer.","quienes_somos":{"titulo":"Más de setenta años sirviendo a nuestra comunidad","descripcion":"La Parroquia San Pedro Nolasco nació del deseo de un pequeño grupo de familias por tener un lugar de encuentro con Dios. Hoy somos una comunidad numerosa que conserva ese mismo espíritu: cercanía, sencillez y servicio.","mision":"Anunciar el Evangelio y acompañar a cada persona en su camino de fe, sin importar de dónde venga ni cuánto haya caminado.","comunidad":"Doce grupos pastorales — coro, catequesis, pastoral familiar, juventud y más — donde cada quien encuentra su manera de servir.","servicio":"Visitas a enfermos, apoyo a familias en necesidad y formación abierta para todas las edades, durante todo el año."},"cantidad_grupos":12,"cantidad_espacios":7,"valores_encabezado":{"titulo":"Lo que sostiene nuestra vida parroquial","descripcion":"Cuatro principios guían todo lo que hacemos: desde la celebración dominical hasta el acompañamiento silencioso de una familia en duelo."},"valores":[{"titulo":"Fe viva","descripcion":"Celebramos los sacramentos con cuidado y reverencia, y cultivamos una oración que acompaña la vida real de cada familia."},{"titulo":"Servicio","descripcion":"Nadie sirve solo. Ministros, coordinadores y voluntarios trabajan juntos para que cada necesidad encuentre una respuesta."},{"titulo":"Comunidad","descripcion":"Aquí nadie es un extraño. Creamos espacios donde jóvenes, adultos y mayores se encuentran y se acompañan."},{"titulo":"Formación","descripcion":"Catequesis para niños, preparación sacramental y círculos de estudio abiertos a quien desee profundizar su fe."},{"titulo":"Caridad","descripcion":"Acompañamos a las familias que atraviesan dificultades con apoyo concreto, discreto y sostenido en el tiempo."},{"titulo":"Tradición","descripcion":"Cuidamos las celebraciones y devociones que nos identifican, heredadas de quienes levantaron esta parroquia."}],"horarios_misa":[{"dias":"Domingo","horas":["08:00","11:00","18:00"]},{"dias":"Lunes a viernes","horas":["18:30"]}],"horarios_oficina":[{"dias":"Lunes a viernes","horario":"09:00 – 13:00 · 15:00 – 19:00"},{"dias":"Sábados","horario":"09:00 – 13:00"}],"contacto":{"titulo":"Estamos aquí para acompañarte","direccion":"3a Avenida 12-40, Zona 1\\nCiudad de Guatemala","correo":"contacto@sanpedronolasco.gt","telefono":"+502 2230 4488"},"texto_pie":"Una comunidad de fe al servicio de las familias de nuestro"}'
WHERE NOT EXISTS (SELECT 1 FROM contenido_landing WHERE id = 1);
